CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 VARCHAR(10) UNIQUE, c1 INTEGER COLLATE NOCASE, c2  DEFAULT 'd');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL, c1 VARCHAR(10) CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT CHECK(c2 IS NULL OR length(c2) < 40), c3, c4 NUMERIC DEFAULT 'd');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(445.47, NULL, x'64', 512, NULL);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 ANY, c1 INTEGER CHECK(c1 IS NULL OR length(c1) < 40), c2 INTEGER, c3 REAL) STRICT;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -2, 4), instr('it''s', 'Ελλάδα'), replace('it''s', '', 'XY'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE '%a_', 'it''s' GLOB '?', char(88, 980), 'it''s' || 'Ελλάδα', 'it''s' < 'Ελλάδα', 'it''s' = 'Ελλάδα' COLLATE NOCASE;
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', -2, 1), instr('Lambda', 'kappa'), replace('Lambda', 'é', ''), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE 'A%', 'Lambda' GLOB '?', char(67, 517), 'Lambda' || 'kappa', 'Lambda' < 'kappa', 'Lambda' = 'kappa' COLLATE NOCASE;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', -1, 0), instr('x_y', 'beta'), replace('x_y', 'e', '_'), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE 'a%', 'x_y' GLOB '*', char(69, 843), 'x_y' || 'beta', 'x_y' < 'beta', 'x_y' = 'beta' COLLATE NOCASE;
SELECT length('epsilon'), upper('epsilon'), lower('epsilon'), substr('epsilon', 4, 4), instr('epsilon', ''), replace('epsilon', 'a', '_'), trim('epsilon'), ltrim('epsilon', 'ab'), hex('epsilon'), quote('epsilon'), unicode('epsilon'), 'epsilon' LIKE 'a%', 'epsilon' GLOB '*[a-m]*', char(85, 297), 'epsilon' || '', 'epsilon' < '', 'epsilon' = '' COLLATE NOCASE;
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', 1, 2), instr('omega', 'iota'), replace('omega', 'é', 'XY'), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE 'a%', 'omega' GLOB 'a*', char(88, 649), 'omega' || 'iota', 'omega' < 'iota', 'omega' = 'iota' COLLATE NOCASE;
SELECT length('café'), upper('café'), lower('café'), substr('café', -2, 1), instr('café', 'delta'), replace('café', 'a', ''), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE '%é%', 'café' GLOB '*[a-m]*', char(69, 640), 'café' || 'delta', 'café' < 'delta', 'café' = 'delta' COLLATE NOCASE;
SELECT length(' pad '), upper(' pad '), lower(' pad '), substr(' pad ', 0, 5), instr(' pad ', '0x1F'), replace(' pad ', 'a', '_'), trim(' pad '), ltrim(' pad ', 'ab'), hex(' pad '), quote(' pad '), unicode(' pad '), ' pad ' LIKE 'A%', ' pad ' GLOB '*[a-m]*', char(85, 313), ' pad ' || '0x1F', ' pad ' < '0x1F', ' pad ' = '0x1F' COLLATE NOCASE;
CREATE UNIQUE INDEX IF NOT EXISTS i1 ON t2(c1, id);
SELECT id, c1 FROM t2 WHERE c1 = 9223372036854775807 ORDER BY c1, id;
SELECT count(*) FROM t2 INDEXED BY i1 WHERE c1 IS NOT NULL;
REINDEX t2;
DROP INDEX IF EXISTS i1;
UPDATE t1 SET c0 = coalesce(c4, id) WHERE coalesce(0, iif(c3, -494, 'zeta'));
DELETE FROM t1 WHERE id % 5 = 1;
SELECT * FROM t1 ORDER BY id DESC, c0, c1 DESC, c2, c3, c4 DESC;
SELECT a.id, b.id, a.id, b.c0 FROM t1 a JOIN t1 b ON a.id < b.id ORDER BY 1, 2 LIMIT 48;
SELECT count(*) FROM t1 a JOIN t1 b USING(id) WHERE (typeof(-2) OR c1 BETWEEN x'6d' AND c4);
